// BookingRoomModal.jsx
import React, { useEffect, useState } from "react";
import {
  Modal,
  Form,
  Input,
  InputNumber,
  Select,
  DatePicker,
  TimePicker,
  Row,
  Col,
  Divider,
  Alert,
  Checkbox,
  Typography,
  Button,
  notification,
} from "antd";
import { CoffeeOutlined } from "@ant-design/icons";
import baseAPI from "../api/baseAPI";
import dayjs from "dayjs";
// Import the new FoodAndDrinksModal component
import FoodAndDrinksModal from "./FoodAndDrinksModal"; // Import allFoodAndDrinksData ด้วย
import { useSelector } from "react-redux";

const { Title, Text } = Typography;

export default function BookingRoomModal({
  open,
  onClose,
  onFinish,
  room,
  // selectedRoomId,
  // roomPrice = 0,
}) {
  const allAmenitiesData = useSelector((state) => state.amenities);

  const groupedAllAmenities = {};
  allAmenitiesData.forEach((amenity) => {
    if (!groupedAllAmenities[amenity.category]) {
      groupedAllAmenities[amenity.category] = [];
    }
    groupedAllAmenities[amenity.category].push({
      label: amenity.name,
      value: amenity.name,
    });
  });

  const categoryOrder = ["Display", "Sound", "Video Conferencing", "Other"];

  const [form] = Form.useForm();
  const [rooms, setRooms] = useState([]);
  const [bookingError, setBookingError] = useState(null);
  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [selectedFoodAndDrinks, setSelectedFoodAndDrinks] = useState([]);
  const [bookingHours, setBookingHours] = useState(0);
  const [amenitiesCost, setAmenitiesCost] = useState(0);
  const [foodCost, setFoodCost] = useState(0);
  const [totalCost, setTotalCost] = useState(0);

  const watchStartTime = Form.useWatch("start_time", form);
  const watchEndTime = Form.useWatch("end_time", form);
  const watchAmenities = Form.useWatch("amenities", form);

  const allFoodAndDrinksData = useSelector((state) => state.foodAndDrinks);

  useEffect(() => {
    fethMeetingRooms();
  }, []);

  useEffect(() => {
    if (open && room?.id) {
      form.setFieldsValue({
        room_id: room.id,
        amenities: [],
        // ไม่ต้อง set food_and_drinks ที่นี่แล้ว เพราะ FoodAndDrinksModal จะจัดการเอง
      });
      setSelectedFoodAndDrinks([]); // Clear selected food/drinks when main modal opens
    } else if (!open) {
      // เมื่อ BookingRoomModal ปิด ให้ reset form และ clear selected food/drinks
      form.resetFields();
      setSelectedFoodAndDrinks([]);
      setBookingError(null);
    }
  }, [open, room.id, form]);

  const fethMeetingRooms = async () => {
    try {
      const result = await baseAPI.get(`/meetingrooms`);
      setRooms(result.data);
    } catch (error) {
      console.error("Failed to fetch rooms:", error);
      notification.error({
        message: "เกิดข้อผิดพลาด",
        description: "ไม่สามารถดึงข้อมูลห้องประชุมได้",
      });
    }
  };

  const onSubmit = async (data) => {
    try {
      const res = await baseAPI.post(`/booking-rooms`, data);

      if (res.status === 201) {
        setBookingError("");
        // ไม่ต้อง resetFields หรือ clear selectedFoodAndDrinks ที่นี่
        // เพราะ useEffect ด้านบนจะจัดการเมื่อ Modal ปิด
        // notification.success({
        //   message: "จองห้องประชุมสำเร็จ",
        //   description: "เจ้าหน้าที่จะติดต่อกลับไปยืนยันการจองของคุณ",
        // });
        onFinish(data); // Call onFinish of parent (RoomDetailsPage) which also closes this modal
      } else if (res.status === 200) {
        const errorMessage =
          res.data?.message ||
          "ขออภัยวันและเวลาดังกล่าวถูกจองแล้ว กรุณาเลือกเวลาอื่น ";
        setBookingError(errorMessage);
      }
    } catch (err) {
      console.error("Booking Error:", err);
      const backendErrorMessage =
        err.response?.data?.message ||
        "ไม่สามารถทำรายการจองได้ กรุณาลองใหม่อีกครั้ง";
      notification.error({
        message: "เกิดข้อผิดพลาด",
        description: backendErrorMessage,
      });
      setBookingError(backendErrorMessage);
    }
  };

  const handleSubmit = (values) => {
    const formattedDate = values.date ? values.date.format("YYYY-MM-DD") : null;
    const formattedStartTime = values.start_time
      ? values.start_time.format("HH:mm") + ":00"
      : null;
    const formattedEndTime = values.end_time
      ? values.end_time.format("HH:mm") + ":00"
      : null;

    const submitData = {
      ...values,
      date: formattedDate,
      start_time: formattedStartTime,
      end_time: formattedEndTime,
      amenities: (values.amenities || [])
        .map((name) => allAmenitiesData.find((a) => a.name === name))
        .filter(Boolean),
      // Use selectedFoodAndDrinks from state
      food_and_drinks: selectedFoodAndDrinks
        .map((name) => {
          // Find the full item object from allFoodAndDrinksData
          return allFoodAndDrinksData.find((item) => item.name === name);
        })
        .filter(Boolean),
    };

    // console.log("Submit", submitData);
    // alert("ระบบยังไม่สมบูรณ์เป็นเพียงตัวอย่างเท่านั้น");

    onSubmit(submitData);
  };

  const handleFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const handleCancel = () => {
    // การ resetFields และ clear selectedFoodAndDrinks ถูกย้ายไปที่ useEffect เมื่อ open เป็น false
    onClose(false);
  };

  // --- Food/Drinks Modal Handlers ---
  const handleOpenFoodModal = () => {
    setIsFoodModalOpen(true);
    // ไม่ต้อง setFieldsValue ที่นี่แล้ว เพราะ FoodAndDrinksModal จะใช้ initialSelectedItems
  };

  const handleCloseFoodModal = () => {
    setIsFoodModalOpen(false);
  };

  // Callback function to receive selected food/drinks from FoodAndDrinksModal
  const handleSaveFoodAndDrinks = (items) => {
    setSelectedFoodAndDrinks(items); // Update the state in BookingRoomModal
    notification.info({
      message: "รายการอาหาร/เครื่องดื่มถูกบันทึกแล้ว",
      description: `เลือกไป ${items.length} รายการ`,
      duration: 3,
    });
  };

  useEffect(() => {
    // 🕒 คำนวณชั่วโมง
    if (watchStartTime && watchEndTime) {
      const start = dayjs(watchStartTime, "HH:mm");
      const end = dayjs(watchEndTime, "HH:mm");
      const diff = end.diff(start, "minute") / 60;
      const roundedHours = Math.max(Math.round(diff * 2) / 2, 0);
      setBookingHours(roundedHours);
    }
  }, [watchStartTime, watchEndTime]);

  useEffect(() => {
    // 💡 คำนวณราคาสิ่งอำนวยความสะดวก
    const cost = (watchAmenities || []).reduce((sum, name) => {
      const item = allAmenitiesData.find((a) => a.name === name);
      return (
        sum + (item && ~~item.price > 0 ? ~~item.price + ~~item.deposit : 0)
      );
    }, 0);
    setAmenitiesCost(cost);
  }, [watchAmenities]);

  useEffect(() => {
    // 🍴 คำนวณอาหาร/เครื่องดื่ม
    const cost = selectedFoodAndDrinks.reduce((sum, name) => {
      const item = allFoodAndDrinksData.find((d) => d.name === name);
      return sum + (item ? ~~item.price : 0);
    }, 0);
    setFoodCost(cost);
    console.log("COST", cost);
  }, [selectedFoodAndDrinks]);

  useEffect(() => {
    // 💰 รวมราคาทั้งหมด
    const roomCost = bookingHours * ~~room.price;
    setTotalCost(
      ~~roomCost +
        ~~amenitiesCost +
        (~~foodCost * form.getFieldValue("number_attendees") || 0)
    );
  }, [bookingHours, amenitiesCost, foodCost, room.price]);

  return (
    <div>
      <Modal
        title={`จองห้องประชุม`}
        open={open}
        onOk={form.submit}
        onCancel={handleCancel}
        cancelText="ยกเลิก"
        okText="จองห้องประชุม"
        destroyOnClose={false} // ตั้งเป็น false เพื่อให้ useEffect จัดการ resetFields
        width={700}
      >
        <Divider />
        <Form
          layout="vertical"
          form={form}
          onFinish={handleSubmit}
          onFinishFailed={handleFinishFailed}
          initialValues={{
            amenities: [],
            // ไม่ต้องมี food_and_drinks ที่นี่แล้ว เพราะจัดการที่ state และส่งไป FoodAndDrinksModal
          }}
        >
          {room?.id ? (
            <Form.Item label="ห้องประชุมที่เลือก">
              <Input
                value={
                  rooms.find((r) => r.id === room?.id)?.title || "กำลังโหลด..."
                }
                readOnly
              />
              <Form.Item name="room_id" hidden initialValue={room?.id}>
                <Input />
              </Form.Item>
            </Form.Item>
          ) : (
            <Form.Item
              name="room_id"
              label="เลือกห้องประชุม"
              rules={[{ required: true, message: "กรุณาเลือกห้องประชุม!" }]}
            >
              <Select
                placeholder="เลือกห้องประชุมที่ต้องการ"
                options={rooms.map((item) => ({
                  value: item.id,
                  label: `${item.title} (รองรับ ${item.capacity} ที่นั่ง)`,
                }))}
              />
            </Form.Item>
          )}

          <Form.Item
            name="booked_by"
            label="ชื่อผู้จอง หรือชื่อหน่วยงาน"
            rules={[
              { required: true, message: "กรุณากรอกชื่อผู้จองหรือหน่วยงาน!" },
            ]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="phone"
            label="เบอร์โทรศัพท์"
            rules={[{ required: true, message: "กรุณากรอกเบอร์โทรศัพท์!" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="email"
            label="Email"
            rules={[{ type: "email", message: "รูปแบบอีเมลไม่ถูกต้อง!" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="number_attendees"
            label="จำนวนผู้เข้าร่วม"
            rules={[{ required: true, message: "กรุณากรอกจำนวนผู้เข้าร่วม!" }]}
          >
            <InputNumber min={1} style={{ width: "100%" }} />
          </Form.Item>

          <Row gutter={16}>
            <Col xs={24} sm={8}>
              <Form.Item
                name="date"
                label="จองวันที่"
                rules={[{ required: true, message: "กรุณาเลือกวันที่!" }]}
              >
                <DatePicker style={{ width: "100%" }} format="YYYY-MM-DD" />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="start_time"
                label="จากเวลา"
                rules={[{ required: true, message: "กรุณาเลือกเวลาเริ่มต้น!" }]}
              >
                <TimePicker
                  style={{ width: "100%" }}
                  format="HH:mm"
                  minuteStep={30}
                />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="end_time"
                label="ถึงเวลา"
                rules={[{ required: true, message: "กรุณาเลือกเวลาสิ้นสุด!" }]}
              >
                <TimePicker
                  style={{ width: "100%" }}
                  format="HH:mm"
                  minuteStep={30}
                />
              </Form.Item>
            </Col>
          </Row>

          <Form.Item name="purpose" label="วัตถุประสงค์ / ความคิดเห็นเพิ่มเติม">
            <Input.TextArea rows={2} />
          </Form.Item>

          <Divider orientation="left">
            <Title level={5}>เลือกสิ่งอำนวยความสะดวกเพิ่มเติม</Title>
          </Divider>

          <Form.Item name="amenities">
            <Checkbox.Group style={{ width: "100%" }}>
              <div style={{ display: "flex", flexDirection: "column" }}>
                {categoryOrder.map((category) => {
                  const amenitiesInThisCategory = groupedAllAmenities[category];
                  if (
                    amenitiesInThisCategory &&
                    amenitiesInThisCategory.length > 0
                  ) {
                    return (
                      <div
                      // key={category}
                      // style={{
                      //   padding: 16,
                      //   border: "1px solid #f0f0f0",
                      //   borderRadius: 8,
                      // }}
                      >
                        <Title level={5} style={{ marginBottom: 8 }}>
                          {category}
                        </Title>
                        <Row gutter={[32, 32]}>
                          {amenitiesInThisCategory.map((option) => {
                            const fullItem = allAmenitiesData.find(
                              (a) => a.name === option.label
                            );
                            const isPaid = fullItem && !fullItem.is_free;
                            return (
                              <Col key={option.value} xs={24} sm={12} md={8}>
                                <Checkbox value={option.value}>
                                  <div
                                    style={{
                                      display: "flex",
                                      flexDirection: "column",
                                    }}
                                  >
                                    <span>{option.label} </span>

                                    <span
                                      style={{
                                        fontSize: "12px",
                                        color:
                                          fullItem.price > 0
                                            ? "#fa541c"
                                            : "#52c41a",
                                      }}
                                    >
                                      {fullItem.price > 0
                                        ? `+฿${fullItem.price}`
                                        : "ฟรี"}
                                    </span>
                                    <Text
                                      style={{ fontSize: 12 }}
                                      type="secondary"
                                    >
                                      {fullItem.deposit > 0
                                        ? "(+ค่ามัดจำ " + fullItem.deposit + ")"
                                        : ""}
                                    </Text>
                                  </div>
                                </Checkbox>
                              </Col>
                            );
                          })}
                        </Row>
                      </div>
                    );
                  }
                  return null;
                })}
              </div>
            </Checkbox.Group>
          </Form.Item>

          {/* --- Integrate FoodAndDrinksModal --- */}
          <Divider orientation="left">
            <Title level={5}>บริการอาหารและเครื่องดื่ม</Title>
          </Divider>
          <Form.Item label="ค่าอาหารคิดตามจำนวนที่นั่งต่อหนึ่งรายการ">
            <Button
              type="dashed"
              icon={<CoffeeOutlined />}
              onClick={handleOpenFoodModal}
              block
              style={{ height: "auto", padding: "10px 15px" }}
            >
              {selectedFoodAndDrinks.length > 0 ? (
                <div style={{ textAlign: "left" }}>
                  <Text strong>
                    เลือกแล้ว {selectedFoodAndDrinks.length} รายการ:
                  </Text>
                  <br />
                  <Text
                    type="secondary"
                    style={{ whiteSpace: "normal", display: "block" }}
                  >
                    {selectedFoodAndDrinks
                      .map(
                        (name) =>
                          allFoodAndDrinksData.find(
                            (item) => item.name === name
                          )?.name || name
                      )
                      .join(", ")}
                  </Text>
                </div>
              ) : (
                "เพิ่มรายการอาหารหรือเครื่องดื่ม"
              )}
            </Button>
            {selectedFoodAndDrinks.length > 0 && (
              <Text
                type="secondary"
                style={{ marginTop: "8px", display: "block" }}
              >
                รวมราคาอาหาร, เครื่องดื่ม /
                {form.getFieldValue("number_attendees")} ที่นั่ง: THB{" "}
                {selectedFoodAndDrinks.reduce((sum, name) => {
                  const item = allFoodAndDrinksData.find(
                    (d) => d.name === name
                  );
                  return (
                    sum +
                    (item
                      ? item.price *
                        Number(form.getFieldValue("number_attendees"))
                      : 0)
                  );
                }, 0)}
              </Text>
            )}
          </Form.Item>

          <Divider orientation="left">
            <Title level={5}>สรุปการจอง</Title>
          </Divider>

          <Row gutter={[16, 8]}>
            <Col span={12}>
              {" "}
              {/* Half width for label */}
              <Text strong>จำนวนชั่วโมง:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              {" "}
              {/* Half width for value, aligned right */}
              <Text>{bookingHours.toFixed(2)} ชั่วโมง</Text>
            </Col>

            <Col span={12}>
              <Text strong>ค่าบริการห้องประชุม:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>THB {(bookingHours * room.price).toLocaleString()}</Text>
            </Col>

            <Col span={12}>
              <Text strong>ค่าบริการสิ่งอำนวยความสะดวก:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>THB {amenitiesCost.toLocaleString()}</Text>
            </Col>

            <Col span={12}>
              <Text strong>ค่าอาหาร/เครื่องดื่ม:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>
                THB{" "}
                {(
                  foodCost * form.getFieldValue("number_attendees") || 0
                ).toLocaleString()}{" "}
                {/* Add .toLocaleString() here too */}
              </Text>
            </Col>

            {/* For the total, you might want it to stand out more */}
            <Col span={12}>
              <Text strong>รวมทั้งสิ้น:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text type="danger" strong style={{ fontSize: "18px" }}>
                THB {totalCost.toLocaleString()}
              </Text>
            </Col>
          </Row>
          <Divider />
          <Form.Item name="promotion_code" label="Promotion code (ถ้ามี)">
            <Input />
          </Form.Item>
        </Form>

        {bookingError && (
          <Alert
            message={bookingError}
            type="error"
            showIcon
            style={{ marginTop: 16 }}
          />
        )}
      </Modal>

      {/* --- Render the new FoodAndDrinksModal component --- */}
      <FoodAndDrinksModal
        open={isFoodModalOpen}
        onClose={handleCloseFoodModal}
        onSave={handleSaveFoodAndDrinks} // Pass the callback function
        initialSelectedItems={selectedFoodAndDrinks} // Pass current selected items
      />
    </div>
  );
}
